\title{The Analytic Rank of an L-Function:\\ A Formal Skeleton for Birch--Swinnerton-Dyer}
\author{Aristotle}
\date{June 19, 2026}

\begin{document}

\begin{abstract}
The Birch and Swinnerton-Dyer (BSD) conjecture predicts that the algebraic rank of
an elliptic curve $E/\Q$ --- the rank $r$ of its finitely generated Mordell--Weil
group $E(\Q)\cong\Z^r\times T$ --- equals the \emph{analytic rank}, the order of
vanishing at $s=1$ of the Hasse--Weil L-function $L(E,s)$. It further predicts the
exact leading Taylor coefficient of $L$ at $s=1$ in terms of the real period
$\Omega_E$, the regulator $\Reg_E$, the order of the Tate--Shafarevich group
$\#\Sha(E)$, the Tamagawa numbers $c_p$, and the torsion order. This paper isolates
and rigorously establishes the \emph{analytic} half of the rank statement. We define
the analytic rank as the natural-number order of vanishing $\ord_{s_0}L$, and prove
four structural theorems any reasonable theory of L-function rank must satisfy:
rank-zero detection, positive-rank detection, leading-term factorization, and
additivity under products. We certify non-vacuity by constructing, for each
$r\in\N$, an explicit model L-function of analytic rank exactly $r$. On the local
side we record the algebraic reformulation of Hasse's bound: a Frobenius eigenvalue
lies on the circle $|z|=\sqrt p$ iff $a^2\le 4p$. All results have been formally
verified.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{The two ranks}
Let $E/\Q$ be an elliptic curve, $y^2=x^3+ax+b$ with $4a^3+27b^2\ne 0$. Its rational
points $E(\Q)$ form an abelian group under the chord--tangent law, and by the
\emph{Mordell--Weil theorem},
\[ E(\Q)\;\cong\;\Z^r\times T, \]
with $T=E(\Q)_{\mathrm{tors}}$ finite and $r\ge 0$ the \emph{algebraic rank}.

For each prime $p$ of good reduction the \emph{trace of Frobenius} is
$a_p=p+1-\#E(\F_p)$, and the \emph{Hasse--Weil L-function} is the Euler product
\[ L(E,s)=\prod_{p\text{ good}}\bigl(1-a_pp^{-s}+p^{1-2s}\bigr)^{-1}\cdot
   \prod_{p\text{ bad}}(\text{local factor}),\qquad \Re(s)>3/2, \]
which continues analytically to $\C$ (modularity). The \emph{analytic rank} is
\[ \rank_{\mathrm{an}}(E):=\ord_{s=1}L(E,s). \]

\subsection{The conjecture}
\begin{conjecture}[BSD, rank form]
$\ord_{s=1}L(E,s)=r$.
\end{conjecture}
\begin{conjecture}[BSD, strong form]
With $r$ the common rank,
\[ \lim_{s\to1}\frac{L(E,s)}{(s-1)^r}
   =\frac{\Omega_E\cdot\Reg_E\cdot\#\Sha(E)\cdot\prod_p c_p}
         {(\#E(\Q)_{\mathrm{tors}})^2}. \]
\end{conjecture}

\subsection{Contribution}
We do not resolve BSD. We give a formally verified \emph{analytic skeleton}: the
unconditional structural properties of the order-of-vanishing invariant, decoupled
from the open identification with the algebraic rank. We work with an abstract
analytic $L:\C\to\C$ and central point $s_0$ (take $s_0=1$ for BSD).

\section{Definitions}

For an analytic function, the \emph{order of vanishing} $\ord_{s_0}L\in\N\cup\{\infty\}$
is the largest $n$ with $(s-s_0)^{-n}L(s)$ analytic and nonzero at $s_0$; it is
$\infty$ iff $L$ vanishes identically near $s_0$.

\begin{definition}[Analytic rank]
$\rank_{\mathrm{an}}(L,s_0):=(\ord_{s_0}L)_{\N}\in\N$, the truncation to $\N$ of the
order of vanishing.
\end{definition}

\begin{definition}[Non-degeneracy]
$L$ is \emph{non-degenerate at $s_0$} if $\ord_{s_0}L\ne\infty$, i.e.\ $L$ is not
identically zero near $s_0$. This is the formal shadow of analytic continuation.
\end{definition}

\begin{definition}[Model L-function]
For $r\in\N$, $c\in\C$, $\ \modelL(r,c)(s):=(s-1)^r\cdot c$.
\end{definition}

\begin{definition}[Local factor and Frobenius]
At a good prime $p$, $L_p(T)=1-a_pT+pT^2$; its reciprocal roots $\alpha,\beta$ ---
the roots of $X^2-a_pX+p$ --- are the \emph{Frobenius eigenvalues}, with
$\alpha+\beta=a_p$ and $\alpha\beta=p$.
\end{definition}

\section{Main Results}

\subsection{Detection theorems}

\begin{theorem}[\texttt{analyticRank\_eq\_zero\_iff}]
If $L$ is analytic and non-degenerate at $s_0$, then
$\rank_{\mathrm{an}}(L,s_0)=0\iff L(s_0)\ne 0$.
\end{theorem}
\begin{proof}[Proof sketch]
The rank is the $\N$-truncation of $\ord_{s_0}L$; truncation yields $0$ when the
order is $0$ or $\infty$, and non-degeneracy excludes $\infty$. The standard
characterization of order $0$ for an analytic function is $L(s_0)\ne 0$.
\end{proof}

\begin{theorem}[\texttt{analyticRank\_pos\_iff}]
Under the same hypotheses, $\rank_{\mathrm{an}}(L,s_0)\ge 1\iff L(s_0)=0$.
\end{theorem}
\begin{proof}[Proof sketch]
Positivity of a natural number is the negation of being zero; negate Theorem~3.1.
\end{proof}

\subsection{Leading-term factorization}

\begin{theorem}[\texttt{analyticRank\_factorization}]
If $L$ is analytic and non-degenerate at $s_0$ with $r=\rank_{\mathrm{an}}(L,s_0)$,
there is an analytic $g$ with $g(s_0)\ne 0$ and, near $s_0$,
$L(s)=(s-s_0)^r\,g(s)$.
\end{theorem}
\begin{proof}[Proof sketch]
This is the universal property of the order of vanishing: order $=n$ iff such a
factorization with $g(s_0)\ne0$ exists. Instantiate $n=r$.
\end{proof}

\noindent The value $g(1)$ is the leading Taylor coefficient predicted by the strong
BSD formula,
$g(1)=\dfrac{\Omega_E\,\Reg_E\,\#\Sha(E)\,\prod_pc_p}{(\#E(\Q)_{\mathrm{tors}})^2}$.

\subsection{Additivity}

\begin{theorem}[\texttt{analyticRank\_mul}]
If $f,g$ are analytic and non-degenerate at $s_0$, then
$\rank_{\mathrm{an}}(fg,s_0)=\rank_{\mathrm{an}}(f,s_0)+\rank_{\mathrm{an}}(g,s_0)$.
\end{theorem}
\begin{proof}[Proof sketch]
Orders add: $f=(s-s_0)^m f_1$, $g=(s-s_0)^n g_1$ with $f_1(s_0),g_1(s_0)\ne0$ give
$fg=(s-s_0)^{m+n}f_1g_1$. Non-degeneracy makes both orders finite, so truncation to
$\N$ commutes with the sum.
\end{proof}

\noindent This is the rank-level Artin/Rankin--Selberg formalism; combined with
Theorem~3.1 it yields isogeny invariance of the analytic rank.

\subsection{Non-vacuity}

\begin{lemma}[\texttt{modelL\_analyticAt}]
For all $r,c$, $\modelL(r,c)$ is analytic everywhere, in particular at $s_0=1$.
\end{lemma}

\begin{theorem}[\texttt{modelL\_analyticRank}]
For all $r\in\N$ and $c\ne0$, $\rank_{\mathrm{an}}(\modelL(r,c),1)=r$.
\end{theorem}
\begin{proof}[Proof sketch]
The factorization $\modelL(r,c)(s)=(s-1)^r\cdot c$ has the form of Theorem~3.3 with
$g\equiv c$, $g(1)=c\ne0$; so the order is $r$, and truncation returns $r$.
\end{proof}

\begin{corollary}[\texttt{modelL\_central\_value}]
For $c\ne0$, $\modelL(r,c)(1)=0\iff r\ge1$.
\end{corollary}

\noindent Theorem~3.7 shows the analytic-rank invariant is surjective onto $\N$:
it is not secretly constant.

\subsection{The local side}

\begin{theorem}[Hasse bound, eigenvalue form]
Let $p$ be prime, $a\in\Z$. A root $z\in\C$ of $X^2-aX+p$ satisfies $|z|=\sqrt p$ iff
$a^2\le 4p$.
\end{theorem}
\begin{proof}[Proof sketch]
The roots are $\tfrac{a\pm\sqrt{a^2-4p}}{2}$. If $a^2\le4p$ they are conjugate and
$|z|^2=\alpha\beta=p$. Conversely $|z|=\sqrt p$ forces $\bar z=\beta$, so the roots
are conjugate and the discriminant $a^2-4p\le0$.
\end{proof}

\section{Algorithms}
\textbf{(A) Analytic rank by series truncation:} given Taylor coefficients
$a_0,a_1,\dots$ of $L$ at $s_0$, the rank is $\min\{n:a_n\ne0\}$; complexity $O(N)$.
\textbf{(B) Trace of Frobenius:} count $\F_p$-points via Legendre symbols, set
$a_p=p+1-\#E(\F_p)$, check $a_p^2\le4p$; complexity $O(p\log p)$.
\textbf{(C) Euler product:} factor $L_p(T)=1-a_pT+pT^2$, verify $|\alpha|=|\beta|=\sqrt p$,
accumulate $\prod_{p\le X}L_p(p^{-s})^{-1}$.

\section{Applications}
Rank-zero finiteness criteria (with Kolyvagin), the congruent number problem
($y^2=x^3-n^2x$), Hasse-bound constraints on cryptographic group orders, and
isogeny-class rank reduction.

\section{Discussion}
The results separate the unconditional analytic structure of BSD from its open
arithmetic content. What remains is the bridge: identifying analytic rank with the
algebraic Mordell--Weil rank and evaluating $g(1)$ by the strong formula. The
non-degeneracy hypothesis is essential because the $\N$-valued rank truncates
$\infty$ to $0$.

\section{Future Work}
(1) Local zeta functional equation from eigenvalue symmetry $\alpha\leftrightarrow p/\alpha$;
(2) sharpness and symmetry of the Hasse interval under $a\mapsto-a$;
(3) full isogeny invariance of analytic rank; (4) the parity bridge
$w=(-1)^{\rank}$.

\section{Conclusion}
We have given a formally verified analytic skeleton for BSD: a clean definition of
analytic rank, four structural theorems, an explicit realizability family, and the
algebraic core of Hasse's bound --- the load-bearing analytic facts on which a
resolution of BSD must rest.

\end{document}

