function TRACE_AND_EIGENVALUES(a, b, p):
    squares <- { y^2 mod p : y in 0..p-1 }
    count <- 1                       # point at infinity
    for x in 0..p-1:
        rhs <- (x^3 + a x + b) mod p
        if rhs == 0:      count <- count + 1
        elif rhs in squares: count <- count + 2
    a_p <- p + 1 - count
    disc <- sqrt(a_p^2 - 4p)         # complex
    alpha, beta <- (a_p +- disc)/2
    return a_p, alpha, beta, (a_p^2 <= 4p)
